// every claim the page uses
function claimsUsed() {
  const s = new Set();
  const add = a => (a || []).forEach(c => s.add(c));
  add(UNDERSTAND.introClaims); add(UNDERSTAND.termsClaims);
  UNDERSTAND.factors.forEach(f => add(f.claims)); UNDERSTAND.why.forEach(w => add(w.claims));
  HEALTH.kinds.forEach(k => add(k.claims)); HEALTH.pathways.forEach(p => add(p.claims)); add(HEALTH.women.gapClaims); HEALTH.women.items.forEach(i => add(i.claims));
  RECORDS.forEach(r => r.ev.forEach(e => add(e.claims)));
  EXAMPLES.forEach(e => add(e.claims)); add(MEASURE.metricsClaims); MEASURE.jurisdictions.forEach(j => add(j.claims));
  return [...s];
}

// llms-full.txt: the same words, as plain text (records filtered to those whose evidence passed, by the builder)
function md(SITE, ok) {
  const okc = id => !ok || ok.has(id);
  const evOf = r => { const ev = r.ev.map(e => ({ type: e.type, claims: e.claims.filter(okc), note: e.note })).filter(e => e.claims.length); return ev.length ? ev : [{ type: "proposal", claims: [], note: r.gap }]; };
  const L = [`## ${TITLE}`, `${SITE}/${SLUG}/`, SUB, DESC, "", `### ${OPEN.q}`, OPEN.a, `${OPEN.label}:`, ...OPEN.stops.map(s => `- ${s.place}: ${s.text}`), OPEN.close, "",
    "### Understand the heat", UNDERSTAND.intro, ...UNDERSTAND.factors.map(f => `- ${f.t}: ${f.d}`), `- ${UNDERSTAND.contact.t}: ${UNDERSTAND.contact.d}`,
    "Four words:", ...UNDERSTAND.terms.map(t => `- ${t.t}: ${t.d}`), ...UNDERSTAND.why.map(w => `${w.t}. ${w.d}`), UNDERSTAND.numbers, "",
    "### Explore a factory (an illustrative garment factory, not a thermal survey)",
    ...ZONES.map(z => `#### ${z.t}\n- Heat sources: ${z.sources.join("; ")}\n- Work: ${z.intensity}\n- Who works here: ${z.who}\n- Ask: ${z.ask.join(" ")}\n- Measure: ${z.measure.join("; ")}\n- Measures to consider: ${z.fixes.map(id => (RECORDS.find(r => r.id === id) || {}).t).filter(Boolean).join("; ")}\n- Depends on: ${z.depends}`), "",
    "### Health and equity", HEALTH.intro, ...HEALTH.kinds.map(k => `- ${k.t}: ${k.d}`), ...HEALTH.pathways.map(p => `- ${p.t}: ${p.d}`),
    `#### ${HEALTH.women.h}`, HEALTH.women.intro, HEALTH.women.gap, ...HEALTH.women.items.map(i => `- ${i.t}: ${i.d}`), HEALTH.women.within, HEALTH.women.agency, "",
    "### Intervention library", `Evidence types: ${Object.values(EV).join("; ")}.`,
    ...FAMILIES.map(f => [`#### ${f.id}. ${f.t}`, f.d, ...RECORDS.filter(r => r.fam === f.id).map(r => {
      const ev = evOf(r);
      return `- ${r.t} [${r.id}]. Addresses: ${r.addresses} How: ${r.how} Where: ${r.where} Works if: ${r.works.join("; ")}. Take care: ${r.caution.join("; ") || "none noted"}. Upfront: ${r.upfront} Running: ${r.recurrent} Owners: ${r.owners} Measure: ${r.measure} Evidence: ${ev.map(e => EV[e.type] + (e.note ? ` (${e.note})` : "")).join("; ")}.`;
    })].join("\n")), "",
    "### Finder: what you observe, and where to look", FINDER.intro, ...CONDITIONS.map(c => `- ${c.t}: ${c.why} Families: ${c.fams.map(id => FAMILIES.find(f => f.id === id).t).join("; ")}. Investigate next: ${c.next}`), "",
    "### Worked examples (illustrative)", ...EXAMPLES.map(e => `#### ${e.t}\n- Observed problem: ${e.problem}\n- Missing information: ${e.missing}\n- Candidate measures: ${e.measures.map(id => RECORDS.find(r => r.id === id).t).join("; ")}\n- Organisational arrangements: ${e.org}\n- Verification: ${e.verify}`), "",
    "### Measure effectiveness", MEASURE.intro, ...MEASURE.metrics.map(m => `- ${m.t}: ${m.d}`), ...MEASURE.practice.map(p => `- ${p}`), "Four levels of evidence that a measure worked:", ...MEASURE.levels.map(l => `- ${l.t}: ${l.d}`), MEASURE.law, ...MEASURE.jurisdictions.map(j => `- ${j.where}: ${j.what}`), "",
    "### Other manufacturing", OTHERS.intro, ...OTHERS.rows.map(r => `- ${r.t}: ${r.d}`), "",
    "### Evidence gaps", ...GAPS.map(g => `- ${g}`), "",
    `Worksheet to print: ${SITE}/${WORKSHEET.slug}/`, ""];
  return L.join("\n");
}

module.exports = { SLUG, TITLE, SUB, DESC, EV, EV_NOTE, OPEN, ENTRIES, UNDERSTAND, ZONES, HEALTH, FAMILIES, RECORDS, CONDITIONS, FINDER, EXAMPLES, MEASURE, OTHERS, GAPS, WORKSHEET, claimsUsed, md };
